"""Distinct Subsequences — count how many ways t appears inside s.

Iterating t backwards lets the counts be updated in place without clobbering the
values the recurrence still needs.

Time: O(n*m)   Space: O(m)
"""


class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        counts = [1] + [0] * len(t)
        for ch in s:
            for j in range(len(t) - 1, -1, -1):
                if t[j] == ch:
                    counts[j + 1] += counts[j]
        return counts[-1]
